"""Benchmark tasks (Lueckmann et al., 2021) with reference samplers.

Gaussian linear: analytic posterior and analytic arbitrary conditionals (joint is Gaussian).
Two moons / Gaussian mixture: 2-d parameters -> reference posterior by exact grid sampling of
prior x analytic likelihood. Likelihood references are exact (simulator).
"""
import math
import numpy as np
import torch


class GaussianLinear:
    name, n_theta, n_x = "gaussian_linear", 10, 10

    def prior(self, n):
        return torch.randn(n, 10) * math.sqrt(0.1)

    def simulate(self, th):
        return th + torch.randn_like(th) * math.sqrt(0.1)

    def edge_mask(self):  # directed M_E (row attends to col); undirected = symmetrized
        M = np.block([[np.eye(10), np.zeros((10, 10))], [np.eye(10), np.eye(10)]])
        return M

    def joint_cov(self):
        I = np.eye(10) * 0.1
        return np.block([[I, I], [I, 2 * I]])

    def conditional(self, n, cond_mask, values, rng):
        """Exact samples of latent vars given conditioned ones (joint Gaussian, zero mean)."""
        C = self.joint_cov(); c = cond_mask; l = ~cond_mask
        if c.sum() == 0:
            mu = np.zeros(l.sum()); S = C
        else:
            K = C[np.ix_(l, c)] @ np.linalg.inv(C[np.ix_(c, c)])
            mu = K @ values[c]
            S = C[np.ix_(l, l)] - K @ C[np.ix_(c, l)]
        return rng.multivariate_normal(mu, S, size=n)

    def posterior(self, n, xo, rng):
        m = np.zeros(20, bool); m[10:] = True
        v = np.zeros(20); v[10:] = xo
        return self.conditional(n, m, v, rng)


def _grid_sample(logp_fn, lo, hi, n, rng, res=800):
    g = np.linspace(lo, hi, res)
    A, B = np.meshgrid(g, g, indexing="ij")
    pts = np.stack([A.ravel(), B.ravel()], 1)
    lp = logp_fn(pts)
    p = np.exp(lp - lp.max()); p /= p.sum()
    idx = rng.choice(len(pts), size=n, p=p)
    d = g[1] - g[0]
    return pts[idx] + rng.uniform(-d / 2, d / 2, size=(n, 2))


class TwoMoons:
    name, n_theta, n_x = "two_moons", 2, 2

    def prior(self, n):
        return torch.rand(n, 2) * 2 - 1

    def simulate(self, th):
        n = th.shape[0]
        a = (torch.rand(n) - 0.5) * math.pi
        r = 0.1 + 0.01 * torch.randn(n)
        p = torch.stack([r * torch.cos(a) + 0.25, r * torch.sin(a)], 1)
        s = torch.stack([-torch.abs(th[:, 0] + th[:, 1]) / math.sqrt(2),
                         (-th[:, 0] + th[:, 1]) / math.sqrt(2)], 1)
        return p + s

    def edge_mask(self):
        return np.block([[np.eye(2), np.zeros((2, 2))], [np.ones((2, 2)), np.tril(np.ones((2, 2)))]])

    def loglik(self, th, xo):
        s0 = -np.abs(th[:, 0] + th[:, 1]) / math.sqrt(2)
        s1 = (-th[:, 0] + th[:, 1]) / math.sqrt(2)
        q0 = xo[0] - s0 - 0.25; q1 = xo[1] - s1
        r = np.sqrt(q0 ** 2 + q1 ** 2)
        lp = -0.5 * ((r - 0.1) / 0.01) ** 2 - np.log(r + 1e-12)
        return np.where(q0 > 0, lp, -np.inf)

    def posterior(self, n, xo, rng):
        return _grid_sample(lambda t: self.loglik(t, xo), -1, 1, n, rng, res=1200)


class GaussianMixture:
    name, n_theta, n_x = "gaussian_mixture", 2, 2

    def prior(self, n):
        return torch.rand(n, 2) * 20 - 10

    def simulate(self, th):
        n = th.shape[0]
        sd = torch.where(torch.rand(n, 1) < 0.5, 1.0, 0.1)
        return th + sd * torch.randn_like(th)

    def edge_mask(self):
        return np.block([[np.eye(2), np.zeros((2, 2))], [np.ones((2, 2)), np.tril(np.ones((2, 2)))]])

    def loglik(self, th, xo):
        d2 = ((th - xo[None]) ** 2).sum(1)
        l1 = -0.5 * d2 - math.log(2 * math.pi)
        l2 = -0.5 * d2 / 0.01 - math.log(2 * math.pi * 0.01)
        return np.logaddexp(l1, l2) + math.log(0.5)

    def posterior(self, n, xo, rng):
        return _grid_sample(lambda t: self.loglik(t, xo), -10, 10, n, rng, res=1500)


class SLCP:
    name, n_theta, n_x = "slcp", 5, 8

    def prior(self, n):
        return torch.rand(n, 5) * 6 - 3

    def simulate(self, th):
        n = th.shape[0]
        m = th[:, :2]
        s1, s2 = th[:, 2] ** 2, th[:, 3] ** 2
        rho = torch.tanh(th[:, 4])
        L = torch.zeros(n, 2, 2)
        L[:, 0, 0] = s1; L[:, 1, 0] = rho * s2; L[:, 1, 1] = s2 * torch.sqrt(1 - rho ** 2)
        z = torch.randn(n, 4, 2)
        x = m[:, None] + torch.einsum("nij,nkj->nki", L, z)
        return x.reshape(n, 8)

    def edge_mask(self):
        from scipy.linalg import block_diag
        Mxx = block_diag(*[np.tril(np.ones((2, 2))) for _ in range(4)])
        return np.block([[np.eye(5), np.zeros((5, 8))], [np.ones((8, 5)), Mxx]])


TASKS = {c.name: c for c in [GaussianLinear, TwoMoons, GaussianMixture, SLCP]}

